import json
import subprocess
import sys

tasks = json.load(open('ci/tasks.json'))
def run(name):
    task = tasks[name]
    for prerequisite in task.get('before', []):
        run(prerequisite)
    if 'command' in task:
        subprocess.run(task['command'], check=True)
    for child in task.get('sequence', []):
        run(child)
run(sys.argv[1])

