import json
import subprocess
import sys

config = json.load(open('ci/scopes.json'))
for mode in config['modes']:
    subprocess.run([sys.executable, 'scripts/prepare.py'], check=True)
    for scope in config['scopes']:
        for filename in scope['files']:
            subprocess.run([sys.executable, 'scripts/check.py', mode, filename], check=True)

