import json
import os
from pathlib import Path

def lookup(values, key):
    if os.environ.get('CATALOG_BACKEND') == 'external-contract-fixture':
        fixtures = json.loads(Path('data/external-catalog.json').read_text())
        return fixtures.get(key)
    return values.get(key)

